script:
frappe.ui.form.on('Hooks File Update', {
    pull_latest_customizations(frm) {
        let module_value = frm.doc.module || "";
        let current_user = frappe.session.user;

        frappe.call({
            method: "upande_hooks_updater.server_scripts.update_hooks_from_recent_customizations.update_hooks_file",
            args: {
                module: module_value,
                currentUser: current_user
            },
            callback: function(response) {
                const data = response.message;

                if (data && data.fixtures) {
                    frm.set_value("customizations", data.fixtures);
                    frm.set_value("my_customizations", JSON.stringify(data.users_customizations, null, 2));

                    if (data.skipped) {
                        const skipped_text = Object.entries(data.skipped)
                            .map(([doctype, names]) => `${doctype}: ${names.join(", ")}`)
                            .join("\n");

                        frm.set_value("skipped_duplicates", skipped_text);
                    } else {
                        frm.set_value("skipped_duplicates", "");
                    }

                    frappe.show_alert({
                        message: __("✅ Fixtures pulled and updated."),
                        indicator: 'green'
                    });

                    frm.save();
                } else {
                    frappe.msgprint("⚠️ No data returned from server.");
                }
            },
            error: function(err) {
                frappe.msgprint("❌ Server error.");
                console.error(err);
            }
        });
    }
});
